    The function needs to work with strings only and should not support integers or floats as input.

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def to_float(x):
        if isinstance(x, str):
            # Replace comma with dot for float conversion
            return float(x.replace(',', '.'))
        else:
            return float(x)

    def to_int(x):
        if isinstance(x, int):
            return x
        elif isinstance(x, float):
            return int(x)
        else:
            # For strings, convert to float first then int
            return int(float(x.replace(',', '.')))

    # Convert inputs to floats for comparison
    try:
        fa = to_float(a)
        fb = to_float(b)
    except ValueError:
        # In case inputs can't be converted to float, return None
        return None

    # If equal return None
    if fa == fb:
        return None

    # Determine the larger value
    if fa > fb:
        larger = a
    else:
        larger = b

    # If the larger value is int or float, return it as int
    if isinstance(larger, (int, float)):
        return int(larger)

    # If the larger value is a string, return it as is
    return larger
