def min_product_tuple(lst):
    if not lst or len(lst) < 2:
        raise ValueError("At least two tuples are required to form pairs.")

    min_product = None
    for i in range(len(lst)):
        for j in range(i + 1, len(lst)):
            # Calculate product of elements of tuple i and tuple j
            product = 1
            # Multiply all elements from both tuples
            for val in lst[i]:
                product *= val
            for val in lst[j]:
                product *= val

            if min_product is None or product < min_product:
                min_product = product

    return min_product
