def re_arrange_tuples(lst, order):
    # Build a mapping from first element to the full tuple
    mapping = {t[0]: t for t in lst}
    used = set()
    result = []
    for key in order:
        tup = mapping.get(key)
        if tup is not None and tup not in used:
            result.append(tup)
            used.add(tup)
        else:
            # Skip keys with no tuple or tuple already used
            pass
    return result
